(() => {
'use strict';
const root=document.getElementById('screen'),D=window.A2_CARDS;
const KEY='greek-navigation-prototype-v1',CARDKEY='greek-a2-card-prototype-v1';
const e=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const read=k=>{try{return JSON.parse(localStorage.getItem(k)||'{}')||{}}catch{return {}}};
const store=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
let saved=read(KEY),level=['A2','B1','B2'].includes(saved.level)?saved.level:'A2',candidate=level;
let state=saved.state&&['home','level','library','grammar','lexicon','verbs','verb','vocabulary','lesson','training','practice','activity','result','exam','exam-task','progress','help-level'].includes(saved.state.route)?saved.state:{route:saved.chosen?'home':'level'};
let history=[],marks=read(CARDKEY).marks||{},seen= saved.seen||{},completed=Array.isArray(saved.completed)?saved.completed:[],activities=saved.activities||{},rewardFlags=saved.rewardFlags||{},examDraft=saved.examDraft||{},selectedTopic='gender',practiceSubject='grammar',practiceType='all',checked=false;
const b=(text,act,cls='')=>`<button class="${cls}" data-action="${act}">${text}</button>`;
const route=(text,to,cls='')=>`<button class="${cls}" data-route="${to}">${text}</button>`;
const modules=D.modules.filter(m=>m.category==='grammar');
const byId=id=>D.cards.find(c=>c.id===id);
const sample={B1:{topic:'Процесс и результат в прошлом',rule:'Чтобы описать фон или действие в процессе, используй παρατατικός. Для отдельного завершённого события — αόριστος. Сравни: διάβαζα — читал(а) в тот момент; διάβασα — прочитал(а).',example:'Όταν με πήρες τηλέφωνο, διάβαζα.\nКогда ты позвонил(а), я читал(а).',question:'Όταν με πήρες τηλέφωνο, ___ ένα βιβλίο.',options:['διάβαζα','θα διαβάσω'],answer:'διάβαζα',feedback:'Здесь описываем действие, происходившее в момент звонка.'},B2:{topic:'Уступка: несмотря на обстоятельства',rule:'Παρόλο που связывает два факта, между которыми есть неожиданное противоречие: дождь шёл, но прогулка состоялась. После παρόλο που здесь используется обычная личная форма глагола.',example:'Παρόλο που έβρεχε, βγήκαμε έξω.\nХотя шёл дождь, мы вышли.',question:'Вставь форму для прошлого: Παρόλο που ___, βγήκαμε έξω.',options:['έβρεχε','να βρέχει'],answer:'έβρεχε',feedback:'Έβρεχε описывает дождь в прошлом. Παρόλο που здесь не требует να.'}};
function persist(){store(KEY,{level,chosen:true,state,seen,completed,activities,rewardFlags,examDraft})}
function mark(id){if(level==='A2'){marks[id]=true;const old=read(CARDKEY);store(CARDKEY,{...old,marks})}else seen[level+':'+id]=true;persist()}
function go(to,params={}){history.push(JSON.parse(JSON.stringify(state)));if(to==='level')candidate=level;state={route:to,...params};checked=false;persist();render()}
function back(){state=history.pop()||{route:'home'};persist();render()}
function returnTask(){while(history.length&&history.at(-1).route!=='exam-task')history.pop();state=history.pop()||{route:'exam-task',skill:'reading'};persist();render()}
function title(t,sub){return `<span class="kicker">${level} · ${sub}</span><h2>${t}</h2>`}
function note(){return level==='A2'?'':`<div class="note">${level}: пример навигации и одной карточки. Полный курс и экзаменационные материалы ещё предстоит подготовить.</div>`}
function levelScreen(){return `<span class="kicker">НАЧНИ ТАМ, ГДЕ ТЕБЕ НУЖНО</span><h2>Твой уровень</h2><p>Можно сразу выбрать B1 или B2. Проходить предыдущие уровни для доступа не нужно.</p>${[['A2','Повседневное общение'],['B1','Больше самостоятельности'],['B2','Свободнее выражать мысли']].map(([l,s])=>`<button class="level-choice" data-level="${l}" aria-pressed="${l===candidate}"><strong>${l}</strong><span>${s}</span></button>`).join('')}<div class="stack">${b('Продолжить с '+candidate,'choose-level','primary full')}${route('Не уверена в уровне','help-level','secondary full')}</div><p class="quiet">Выбор можно изменить в любой момент. Прогресс и коллекция сохраняются.</p>`}
function home(){return `${title('Твой греческий','Главная')}${note()}<div class="card hero"><span class="badge">В своём темпе</span><h3>Что хочется сделать сегодня?</h3><p>Потренироваться, разобраться в теме или подготовиться к экзамену.</p>${route('Начать тренировку','training','primary full')}</div>${activities[level]?`<div class="card"><h3>Есть незавершённая сессия</h3>${b('Продолжить','resume-activity','full')}</div>`:''}<button class="topic" data-route="exam"><b>Подготовка к ${level} →</b><span>Чтение · слушание · письмо · говорение</span></button><button class="topic" data-route="library"><b>Разобраться в конкретной теме →</b><span>Грамматика · лексика · глаголы</span></button><button class="topic" data-route="practice"><b>Знаю, что хочу повторить →</b><span>Выбрать тему и упражнение самой</span></button><p class="quiet">Подготовка к экзамену — один из маршрутов. Материалами можно пользоваться отдельно.</p>`}
function library(){return `${title('Материалы','Библиотека')}${note()}<p>Открой нужную тему без обязательного порядка.</p><button class="topic" data-route="grammar"><b>Грамматика →</b><span>Понятное правило → пример → отработка</span></button><button class="topic" data-route="lexicon"><b>Лексика →</b><span>Слова в ситуациях, а не отдельные списки</span></button><button class="topic" data-route="verbs"><b>Глаголы →</b><span>Формы, времена, озвучка и практика</span></button><div class="card"><h3>Нужен экзаменационный маршрут?</h3>${route('Подготовка к '+level,'exam','full')}</div><p class="quiet">Базовые темы остаются доступны: из B1 можно открыть артикли A2, не меняя свой уровень.</p>${b('Открыть базу: артикли A2','foundation','text-button')}`}
function grammar(){return `${title('Грамматика','Материалы')}${note()}<p>Сначала понять, затем попробовать.</p>${level==='A2'?modules.map(m=>{const total=D.cards.filter(c=>c.moduleId===m.id).length,done=D.cards.filter(c=>c.moduleId===m.id&&marks[c.id]).length;return `<button class="topic" data-topic="${m.id}"><span>${done} из ${total} карточек пройдено</span><b>${e(m.title)}</b><span>${e(m.subtitle)}</span><div class="progress"><i style="width:${done/total*100}%"></i></div></button>`}).join(''):`<button class="topic" data-topic="demo"><span>Демо · ${seen[level+':demo']?1:0} из 1 карточек просмотрено</span><b>${e(sample[level].topic)}</b><span>Объяснение и пример упражнения</span></button>${b('Повторить базу: артикли A2','foundation','text-button')}`}`}
function lexicon(){return `${title('Лексика','Материалы')}${note()}<p>Слово → выражение → ситуация.</p>${['В кафе','Город и транспорт','Дом и повседневность'].map((x,i)=>`<button class="topic" data-vocabulary="${i}"><b>${x} →</b><span>Посмотреть образец карточки</span></button>`).join('')}`}
function vocabulary(){const words=[['ο καφές','кофе','Θα ήθελα έναν καφέ, παρακαλώ.','Я бы хотела кофе, пожалуйста.'],['ο σταθμός','станция, вокзал','Πού είναι ο σταθμός;','Где вокзал?'],['το σπίτι','дом','Το σπίτι είναι κοντά στο κέντρο.','Дом находится недалеко от центра.']][state.item||0];return `${title(words[0],'Лексика · образец')}<p>${words[1]}</p><div class="example" lang="el">${words[2]}</div><p>${words[3]}</p><div class="stack">${b('Потренировать выражение','train-lexicon','primary full')}${b('Как меняется артикль?','lex-grammar','full')}${route('Открыть глаголы','verbs','full')}</div><p class="quiet">Лексика связана с грамматикой через конкретную фразу. Пример экрана; это не полный набор слов уровня.</p>`}
function verbs(){return `${title('Греческие глаголы','Материалы')}${note()}<p>Твой инструмент для самостоятельной работы с формами.</p><button class="topic" data-route="verb"><b lang="el">γράφω →</b><span>писать · γράφω / έγραψα / θα γράψω</span></button><div class="card"><h3>Самостоятельная практика</h3><p>Выбираешь глаголы, время и упражнение.</p>${b('Выбрать упражнение','verbs-practice','full')}</div><div class="split">${route('Грамматика','grammar')}${route('Подготовка к '+level,'exam')}</div>`}
function verb(){return `${title('γράφω','Глаголы · писать')}<div class="example" lang="el">γράφω · пишу\nέγραψα · написал(а)\nθα γράψω · напишу</div><div class="card"><h3>Как выбрать время?</h3><p>Разобраться на примере: каждый день, вчера или завтра.</p>${b('Открыть объяснение','verb-grammar','full')}</div><div class="stack">${b('Тренировать формы','train-verbs','primary full')}${b('Самой выбрать упражнение','verbs-practice','full')}${b('Лексика: повседневные дела','verb-lexicon','text-button')}</div>`}
function lesson(){const base=state.foundation||level==='A2',topic=state.topic||'gender';const items=D.cards.filter(c=>c.moduleId===topic&&c.stage==='introduction');const idx=state.step||0,c=items[idx]||items[0];const s=base?{topic:c.prompt,rule:c.body,example:c.example}:sample[level];return `<span class="crumb">${state.fromExam?'Из экзаменационного задания':state.foundation?'База A2 · твой уровень остаётся '+level:'Материалы → Грамматика'}</span><span class="kicker">${base?'A2':'ДЕМО '+level} · ОБЪЯСНЕНИЕ</span><h2>${e(s.topic)}</h2><p>${e(s.rule)}</p><div class="example" lang="el">${e(s.example)}</div>${base?`<p class="quiet">Объяснение ${idx+1} из 2. В теме 6 карточек: 2 объяснения и 4 задания.</p>`:''}<div class="stack">${base&&idx===0?b('Понятно → частая ошибка','lesson-next','primary full'):(state.foundation&&level!=='A2'?'<a href="../a2-cards/?view=practice&topic='+topic+'">Потренировать это правило A2 →</a>':b('Понятно → потренировать','lesson-train','primary full'))}${state.foundation&&level!=='A2'?'<a href="../a2-cards/?view=practice&topic='+topic+'">Открыть отработку базы A2 →</a>':b('Перейти в самостоятельную практику','lesson-practice','full')}${state.fromExam?b('Вернуться к моему ответу','return-exam','text-button'):b('Назад к разделу','back','text-button')}</div>`}
function training(){return `${title('Тренировка','Приложение ведёт')}${note()}<p>Приложение соединяет грамматику, слова и ситуации в одну короткую сессию.</p><div class="card hero"><h3>${level==='A2'?'Три задания для примера':'Одно задание для примера'}</h3><p>${level==='A2'?'Артикль → форма глагола → короткое объявление.':'Посмотри механику на одной демонстрационной карточке.'}</p>${level==='A2'?'<a class="launch" href="../a2-cards/?view=training">Начать тренировку A2 →</a>':b('Посмотреть пример','start-training','primary full')}${level==='A2'?b('Показать только переходы макета','start-training','text-button'):''}</div><p class="quiet">В полной версии — подбор по выбранному уровню и сложным темам. В прототипе последовательность готовая.</p>${activities[level]?b('Продолжить сохранённую','resume-activity','full'):''}<div class="card"><h3>Хочется выбирать самой?</h3>${route('Самостоятельная практика','practice','full')}</div>`}
function practice(){return `${title('Практика','Ты управляешь')}${note()}<p>Выбери содержание и формат. Обязательного маршрута здесь нет.</p><label>Что повторять<select id="practice-subject"><option value="grammar" ${practiceSubject==='grammar'?'selected':''}>Грамматика</option><option value="lexicon" ${practiceSubject==='lexicon'?'selected':''}>Лексика</option><option value="verbs" ${practiceSubject==='verbs'?'selected':''}>Глаголы</option></select></label>${level==='A2'&&practiceSubject==='grammar'?`<label>Тема<select id="practice-topic">${modules.map(m=>`<option value="${m.id}" ${m.id===selectedTopic?'selected':''}>${e(m.title)}</option>`).join('')}</select></label>`:''}<label>Упражнение<select id="practice-type"><option value="all" ${practiceType==='all'?'selected':''}>Все доступные</option><option value="choice" ${practiceType==='choice'?'selected':''}>Выбор ответа</option><option value="input" ${practiceType==='input'?'selected':''}>Ввод формы</option></select></label>${level==='A2'?'<a class="launch" href="../a2-cards/?view=practice&topic='+(practiceSubject==='verbs'?'verb-time':selectedTopic)+'">Открыть существующую практику A2 →</a>':b('Посмотреть пример','start-practice','primary full')}${level==='A2'?b('Показать только переходы макета','start-practice','text-button'):''}<p id="practice-message" role="status" class="quiet"></p><p class="quiet">В основном приложении текущая практика глаголов сохраняет свои настройки и механику. Здесь показан общий вход для будущих разделов.</p>`}
function exam(){return `${title('Подготовка к '+level,'Экзаменационный маршрут')}${note()}<p>Не отдельная копия курса: используем знакомую грамматику и лексику в четырёх навыках.</p>${[['reading','Чтение','Письма, объявления, детали'],['listening','Слушание','Диалоги и короткие сообщения'],['writing','Письмо','Свой связный текст'],['speaking','Говорение','Ответы, описания, диалоги']].map(([id,t,sub])=>`<button class="topic" data-skill="${id}"><b>${t} →</b><span>${sub}</span></button>`).join('')}<p class="quiet">В этом прототипе можно проверить переход из задания в объяснение и обратно. Это не пробный экзамен.</p>`}
const examCard={prompt:'Когда можно попасть в банк?',context:'Η τράπεζα λειτουργεί από Δευτέρα έως Παρασκευή, 08:00–14:00. Το Σάββατο και την Κυριακή είναι κλειστή.',options:['Во вторник в 10:00','В субботу в 10:00','Во вторник в 16:00'],answer:'Во вторник в 10:00'};
function examTask(){const skill=state.skill||'reading',draft=examDraft[level+':'+skill]||{},self=skill==='writing'||skill==='speaking',names={reading:'Чтение',listening:'Слушание',writing:'Письмо',speaking:'Говорение'};return `${title(names[skill],'Подготовка к '+level)}${level!=='A2'?note():''}<p class="quiet">Пример переходов. ${skill==='listening'?'Аудиозапись будет добавлена; здесь показан экран задания.':level!=='A2'?'Ниже базовый образец интерфейса, не задание экзамена '+level+'.':''}</p>${self?`<h3>${skill==='writing'?'Напиши другу о своём дне':'Расскажи о своём обычном дне'}</h3><label for="exam-response">${skill==='writing'?'Черновик':'Опорные слова'}<input id="exam-response" value="${e(draft.text||'')}" placeholder="Το πρωί…"></label>`:`<div class="example" lang="el">${e(examCard.context)}</div><h3>${examCard.prompt}</h3>${examCard.options.map((x,i)=>`<button class="answer" data-exam-answer="${i}" aria-pressed="${draft.answer===x}">${e(x)}</button>`).join('')}`}<div class="stack">${b('Не понимаю правило → объяснение','exam-help','full')}${b('Продолжить','exam-feedback','primary full')}</div><p class="quiet">Ответ сохранится при переходе в грамматику.</p>${draft.review?`<div class="feedback"><b>${self?'Самопроверка':draft.answer===examCard.answer?'Верно':'Разберём ответ'}</b><p>${self?'Есть ли последовательность действий и связки? Для оценки языка нужна отдельная проверка.':'Банк открыт по будням с 08:00 до 14:00. Во вторник в 10:00 подходят и день, и время.'}</p></div>`:''}`}
function getLexCard(){return {id:'lex-demo',prompt:'Выбери: «Я бы хотела кофе»',context:'В кафе · пример выражения',options:['Θα ήθελα έναν καφέ.','Πού είναι ο σταθμός;'],answer:'Θα ήθελα έναν καφέ.',feedback:'Θα ήθελα έναν καφέ — вежливый способ заказать кофе.'}}
function demoCard(){const s=sample[level];return {id:level+'-demo',prompt:s.question,options:s.options,answer:s.answer,feedback:s.feedback}}
function card(id){return id==='lex-demo'?getLexCard():id.endsWith('-demo')?demoCard():byId(id)}
function start(mode,kind,topic){let ids;if(level!=='A2')ids=[level+'-demo'];else if(kind==='lexicon')ids=['lex-demo'];else if(kind==='verbs')ids=D.cards.filter(c=>c.moduleId==='verb-time'&&c.stage==='drill').map(c=>c.id);else if(kind==='grammar')ids=D.cards.filter(c=>c.moduleId===(topic||selectedTopic)&&c.stage!=='introduction').map(c=>c.id);else ids=['gender-drill-1','verb-time-drill-1','reading-detail'];if(mode==='practice'&&practiceType!=='all')ids=ids.filter(id=>{const c=card(id);return (c.type||'choice')===practiceType});if(!ids.length){document.getElementById('practice-message').textContent='В образце нет этого формата. Выбери «Все доступные».';return}const activity={route:'activity',mode,kind,topic,ids,index:0,answer:'',result:null,first:[],sessionId:Date.now()+':'+Math.random().toString(36).slice(2),retryAdded:[]};activities[level]=activity;go('activity',activity)}
function activity(){const c=card(state.ids[state.index]);if(!c){state={route:'training'};return training()}return `${title(state.mode==='training'?'Тренировка':'Практика',`${state.index+1} из ${state.ids.length} заданий`)}<div class="progress"><i style="width:${state.index/state.ids.length*100}%"></i></div><h3>${e(c.prompt)}</h3>${c.context?`<div class="example" lang="el">${e(c.context)}</div>`:''}${c.options?c.options.map((x,i)=>`<button class="answer" data-answer="${i}" aria-pressed="${state.answer===x}" ${state.result!==null?'disabled':''}>${e(x)}</button>`).join(''):`<label>Ответ<input id="activity-response" lang="el" value="${e(state.answer)}" ${state.result!==null?'disabled':''}></label>`}${state.result===null?`<div class="stack"><button id="activity-check" class="primary full" data-action="check" ${!state.answer.trim()?'disabled':''}>Проверить</button>${b('Показать объяснение','activity-help','text-button')}</div>`:`<div class="feedback ${state.result?'':'wrong'}"><b>${state.result?'Верно!':'Разберём ответ'}</b><p>${!state.result?'Правильный ответ: '+e(c.answer)+'. ':''}${e(c.feedback)}</p></div>${b(state.index+1===state.ids.length?'Завершить':'Продолжить','next','primary full')}`}<p class="quiet">${state.mode==='training'?'Сложная карточка вернётся в конце этой короткой сессии.':'Ты выбрала тему и формат самостоятельно.'}</p>`}
function result(){return `${title('Хорошая работа','Сессия завершена')}<div class="card hero"><span class="num">${state.correct} из ${state.total}</span><p>Верно с первой попытки.</p></div><p>Общий прогресс сохраняется при смене уровня.</p><div class="stack">${route('Посмотреть награду','progress','primary full')}${route('Продолжить своим маршрутом','home','full')}${route('Выбрать другую тему','library','full')}</div>`}
function progress(){const count=completed.length;const rewards=[{name:'Оливковая веточка',icon:'🫒',earned:rewardFlags.olive,condition:'Прочитать объяснение и завершить отработку грамматики'},{name:'Кофе на вынос',icon:'☕',earned:rewardFlags.coffee,condition:'Завершить первую тренировку'},{name:'Бутылочка Коммандарии',icon:'🍷',earned:count>=3,condition:'Завершить три сессии'}];return `${title('Мой Кипр','Прогресс и коллекция')}<p>Небольшие открытия в языке — маленькие находки на острове.</p><div class="card"><b>${count} сессий завершено</b><p class="quiet">Все уровни вместе. Выбранный уровень: ${level}.</p></div><div class="reward-grid">${rewards.map(r=>`<div class="reward ${r.earned?'':'locked'}"><div class="symbol" aria-hidden="true">${r.icon}</div><div><strong>${r.name}</strong><br><span>${r.earned?'Открыто · ':''}${r.condition}</span></div></div>`).join('')}</div><p class="quiet">Цифровая коллекция прототипа. Эмодзи — временные обозначения; далее — единая серия иллюстраций, включая стаканчик кофе и бутылочку Коммандарии.</p>${route('Вернуться к занятиям','home','text-button')}`}
function helpLevel(){return `<span class="kicker">БЕЗ ОБЯЗАТЕЛЬНОГО ТЕСТА</span><h2>Можно попробовать</h2><p>A2 — если нужны повседневные фразы и опора на базовую грамматику.</p><p>B1 — если можешь рассказать о событиях и планах, но хочешь говорить самостоятельнее.</p><p>B2 — если хочешь работать с более сложными текстами и аргументами.</p><p class="quiet">Это ориентир для выбора маршрута, не оценка владения языком. В дальнейшем можно добавить короткую диагностику.</p>${route('Выбрать уровень','level','primary full')}`}
const screens={level:levelScreen,home,library,grammar,lexicon,vocabulary,verbs,verb,lesson,training,practice,exam,'exam-task':examTask,activity,result,progress,'help-level':helpLevel};
function render(){document.getElementById('level-pill').textContent=level+' ▾';document.getElementById('app-title').textContent=state.route==='level'?'Начало':'Твой греческий';document.getElementById('back').disabled=history.length===0;root.innerHTML=(screens[state.route]||home)();root.scrollTop=0;const section=['grammar','lexicon','verbs','verb','lesson','vocabulary'].includes(state.route)?'library':state.route==='activity'?state.mode:state.route==='exam'||state.route==='exam-task'?'home':state.route;document.querySelectorAll('#bottom-nav button').forEach(x=>{if(x.dataset.route===section)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});if(state.route==='activity'){activities[level]=JSON.parse(JSON.stringify(state));persist()}}
function check(){if(state.result!==null||!state.answer.trim())return;const c=card(state.ids[state.index]);state.result=state.answer.normalize('NFC').trim().toLocaleLowerCase('el')===c.answer.normalize('NFC').trim().toLocaleLowerCase('el');if(!state.first.some(x=>x.id===c.id))state.first.push({id:c.id,correct:state.result});if(!state.result&&state.mode==='training'&&!state.retryAdded.includes(c.id)){state.retryAdded.push(c.id);state.ids.push(c.id)}if(byId(c.id))mark(c.id);persist();render()}
function finish(){if(!completed.includes(state.sessionId)){completed.push(state.sessionId);if(state.mode==='training')rewardFlags.coffee=true;if(state.kind==='grammar'&&seen['read:'+level])rewardFlags.olive=true}const summary={correct:state.first.filter(x=>x.correct).length,total:state.first.length};delete activities[level];go('result',summary)}
document.addEventListener('click',ev=>{const target=ev.target.closest('button');if(!target)return;if(target.id==='back'){back();return}if(target.id==='level-pill'){go('level');return}if(target.dataset.route){go(target.dataset.route);return}if(target.dataset.level){candidate=target.dataset.level;render();return}if(target.dataset.topic){selectedTopic=target.dataset.topic;go('lesson',{topic:target.dataset.topic,step:0});return}if(target.dataset.vocabulary){go('vocabulary',{item:Number(target.dataset.vocabulary)});return}if(target.dataset.skill){go('exam-task',{skill:target.dataset.skill});return}if(target.dataset.answer!==undefined){state.answer=card(state.ids[state.index]).options[Number(target.dataset.answer)];persist();render();return}if(target.dataset.examAnswer!==undefined){const key=level+':'+(state.skill||'reading');examDraft[key]={...examDraft[key],answer:examCard.options[Number(target.dataset.examAnswer)]};persist();render();return}
 const a=target.dataset.action;if(!a)return;switch(a){case'choose-level':level=candidate;selectedTopic='gender';practiceType='all';history=[];state={route:'home'};persist();render();break;case'back':back();break;case'foundation':go('lesson',{foundation:true,topic:'articles',step:0});break;case'lesson-next':{if(level==='A2'||state.foundation){const c=D.cards.find(c=>c.moduleId===(state.topic||'gender')&&c.stage==='introduction');if(state.foundation&&level!=='A2'){seen['foundation:'+c.id]=true}else mark(c.id)}state.step=1;seen['read:'+level]=true;persist();render();break}case'lesson-train':seen['read:'+level]=true;if(level==='A2')mark(D.cards.filter(c=>c.moduleId===(state.topic||'gender')&&c.stage==='introduction')[state.step||0].id);if(state.foundation&&level!=='A2'){go('practice',{foundation:true});return}start('training','grammar',state.topic);break;case'lesson-practice':selectedTopic=state.topic||'gender';practiceSubject='grammar';go('practice');break;case'verb-grammar':go('lesson',{topic:'verb-time',step:0});break;case'lex-grammar':go('lesson',{topic:'cases',step:0});break;case'verb-lexicon':go('vocabulary',{item:2});break;case'verbs-practice':practiceSubject='verbs';go('practice');break;case'train-verbs':start('training','verbs');break;case'train-lexicon':start('training','lexicon');break;case'start-training':start('training','mixed');break;case'start-practice':start('practice',practiceSubject,selectedTopic);break;case'resume-activity':if(activities[level])go('activity',JSON.parse(JSON.stringify(activities[level])));break;case'exam-help':go('lesson',{topic:['writing','speaking'].includes(state.skill)?'verb-time':'prepositions',step:0,fromExam:true,foundation:level!=='A2'});break;case'return-exam':returnTask();break;case'exam-feedback':{const key=level+':'+(state.skill||'reading');examDraft[key]={...examDraft[key],review:true};persist();render();break}case'activity-help':go('lesson',{topic:byId(state.ids[state.index])?.moduleId==='exam-skills'?'prepositions':byId(state.ids[state.index])?.moduleId||'gender',step:0});break;case'check':check();break;case'next':if(state.index+1>=state.ids.length){finish();return}state.index++;state.answer='';state.result=null;persist();render();break;
 }});
root.addEventListener('change',ev=>{if(ev.target.id==='practice-subject'){practiceSubject=ev.target.value;practiceType='all';render()}if(ev.target.id==='practice-topic')selectedTopic=ev.target.value;if(ev.target.id==='practice-type')practiceType=ev.target.value});
root.addEventListener('input',ev=>{if(ev.target.id==='activity-response'){state.answer=ev.target.value;activities[level]=JSON.parse(JSON.stringify(state));persist();document.getElementById('activity-check').disabled=!state.answer.trim()}if(ev.target.id==='exam-response'){const key=level+':'+state.skill;examDraft[key]={...examDraft[key],text:ev.target.value};persist()}});
render();
})();
